-- PROPOSED ONLY. Reviewed against PR47 b946d07 and its immutable PR23 fixtures.
-- Forward fix after the financial core including charge confirmation. This file
-- was generated by `supabase migration new culqi_pending_charge_guard`.
-- No data reset, reservation release, provider request or credential change.
begin;

do $$
declare reviewed record; installed record;
begin
  -- Compatibility fingerprints prevent silently replacing an unknown deployed
  -- implementation. Accept the reviewed baseline or this exact forward version
  -- so replay remains safe. Hash prosrc, not version-formatted function DDL.
  for reviewed in select * from (values
    ('public.prepare_culqi_token_session(uuid)',
      array['p_order_id']::text[],
      'bb132f441bebc8928bc81051c3a55fa4','search_path=public',
      '17d401290cac5e30523df08ce8c253a2','search_path=pg_catalog, public'),
    ('public.claim_culqi_charge(uuid,text,text,boolean)',
      array['p_order_id','p_source_id','p_device_id','p_has_3ds']::text[],
      '89665a9d6b9d62dfef41950f07cc018d','search_path=public',
      '83e926c4cf8ccc98a5a3e0332bdedf3d','search_path=pg_catalog, public'),
    ('public.confirm_culqi_charge_result(uuid,uuid,uuid,timestamptz,text,text,jsonb)',
      array['p_order_id','p_checkout_session_id','p_charge_attempt_id','p_observed_at',
        'p_provenance','p_mode','p_observation']::text[],
      'f33f8b2a854859252c0024483efd6b22','search_path=pg_catalog, public',
      'f33f8b2a854859252c0024483efd6b22','search_path=pg_catalog, public')
  ) as expected(signature,argnames,baseline_hash,baseline_config,fixed_hash,fixed_config)
  loop
    select p.*,r.rolname,l.lanname into installed
      from pg_catalog.pg_proc p join pg_catalog.pg_roles r on r.oid=p.proowner
      join pg_catalog.pg_language l on l.oid=p.prolang
      where p.oid=to_regprocedure(reviewed.signature);
    if not found then
      raise exception 'Pending charge guard requires the reviewed financial core';
    end if;
    if installed.prorettype is distinct from 'jsonb'::regtype or installed.proretset
      or installed.rolname in ('anon','authenticated','service_role')
      or installed.lanname is distinct from 'plpgsql' or installed.prosecdef is distinct from true
      or installed.prokind is distinct from 'f' or installed.proisstrict
      or installed.provolatile is distinct from 'v' or installed.proparallel is distinct from 'u'
      or installed.proleakproof or installed.prosupport<>0::oid or installed.probin is not null
      or installed.proargnames is distinct from reviewed.argnames
      or installed.proargmodes is not null or installed.proallargtypes is not null
      or installed.pronargdefaults<>0
      or not ((md5(installed.prosrc)=reviewed.baseline_hash
          and installed.proconfig is not distinct from array[reviewed.baseline_config])
        or (md5(installed.prosrc)=reviewed.fixed_hash
          and installed.proconfig is not distinct from array[reviewed.fixed_config]))
      or has_function_privilege('anon',installed.oid,'EXECUTE')
      or has_function_privilege('authenticated',installed.oid,'EXECUTE')
      or not has_function_privilege('service_role',installed.oid,'EXECUTE') then
      raise exception 'Pending charge guard requires the reviewed financial core';
    end if;
  end loop;
end $$;

create or replace function public.prepare_culqi_token_session(p_order_id uuid)
returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $$
declare o public.orders%rowtype; a public.payment_attempts%rowtype; attempt_count integer;
begin
  -- The authoritative eligibility check and the attempt insertion share the
  -- order lock. A stale HTTP pending read cannot reopen a failed reservation.
  select * into o from public.orders where id=p_order_id for update;
  if not found or o.payment_provider is distinct from 'culqi' or o.payment_lane is distinct from 'token'
    or o.payment_status is distinct from 'pending' or o.status is distinct from 'payment_pending_review'
    or o.payment_order_id is not null or o.payment_charge_id is not null
    or o.payment_reconciliation_required is distinct from false or o.payment_reconciliation_reason is not null
    or o.payment_preparation_claimed is distinct from false or o.payment_charge_state is distinct from 'idle'
    or o.payment_charge_attempt_id is not null or o.payment_charge_source_id is not null
    or o.payment_charge_device_id is not null or o.payment_paid_at is not null
    or o.payment_expires_at is null or not isfinite(o.payment_expires_at)
    or o.payment_expires_at<=clock_timestamp() or o.payment_currency is distinct from 'PEN'
    or o.payment_amount_minor is null or o.payment_amount_minor<=0
    or o.total_amount is null or round(o.total_amount*100) is distinct from o.payment_amount_minor::numeric then
    raise exception 'Token payment session is blocked or expired';
  end if;
  perform 1 from public.payment_attempts where order_id=o.id and provider='culqi' order by id for update;
  insert into public.payment_attempts(order_id,provider,provider_order_id,amount_minor,currency_code,expires_at,payment_method)
    values(o.id,'culqi',null,o.payment_amount_minor,'PEN',o.payment_expires_at,'token')
    on conflict (order_id) where provider='culqi' and provider_order_id is null do nothing;
  select count(*) into attempt_count from public.payment_attempts where order_id=o.id and provider='culqi';
  select * into a from public.payment_attempts where order_id=o.id and provider='culqi' and provider_order_id is null;
  if not found or attempt_count<>1 or a.status is distinct from 'pending'
    or a.paid_at is not null or a.provider_charge_id is not null
    or a.amount_minor is distinct from o.payment_amount_minor or a.currency_code is distinct from 'PEN'
    or a.expires_at is distinct from o.payment_expires_at or o.payment_expires_at<=clock_timestamp() then
    -- An exception also rolls back any attempted insertion; existing failure
    -- evidence is never reset to pending to make a retry appear eligible.
    raise exception 'Token payment session is blocked or expired';
  end if;
  return jsonb_build_object('sessionId',a.id,'amount',o.payment_amount_minor,'expiresAt',o.payment_expires_at);
end $$;

create or replace function public.claim_culqi_charge(
  p_order_id uuid, p_source_id text, p_device_id text, p_has_3ds boolean
) returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $$
declare o public.orders%rowtype; a public.payment_attempts%rowtype; attempt_id uuid; attempt_count integer;
begin
  select * into o from public.orders where id=p_order_id for update;
  if not found or o.payment_provider is distinct from 'culqi' then raise exception 'Culqi order not found'; end if;
  if o.payment_status='paid' then return jsonb_build_object('state','paid','claimed',false); end if;
  if o.payment_status is distinct from 'pending' or o.status is distinct from 'payment_pending_review'
    or o.payment_reconciliation_required is distinct from false or o.payment_reconciliation_reason is not null
    or o.payment_preparation_claimed is distinct from false or o.payment_paid_at is not null
    or o.payment_expires_at is null or not isfinite(o.payment_expires_at)
    or o.payment_expires_at<=clock_timestamp() or o.payment_order_id is not null or o.payment_lane is distinct from 'token'
    or o.payment_currency is distinct from 'PEN' or o.payment_amount_minor is null or o.payment_amount_minor<=0
    or o.total_amount is null or round(o.total_amount*100) is distinct from o.payment_amount_minor::numeric then
    return jsonb_build_object('state','blocked','claimed',false);
  end if;
  -- Same order -> attempts order as preparation, finish and confirmation. Neither
  -- entry point acquires a batch lock after an order lock, avoiding a lock cycle
  -- with webhook/reservation operations that lock batch -> order -> attempts.
  perform 1 from public.payment_attempts where order_id=o.id and provider='culqi' order by id for update;
  get diagnostics attempt_count=row_count;
  select * into a from public.payment_attempts where order_id=o.id and provider='culqi' and provider_order_id is null;
  if not found or attempt_count<>1 or a.status is distinct from 'pending' or a.paid_at is not null
    or a.amount_minor is distinct from o.payment_amount_minor or a.currency_code is distinct from 'PEN'
    or a.expires_at is distinct from o.payment_expires_at or o.payment_expires_at<=clock_timestamp() then
    return jsonb_build_object('state','blocked','claimed',false);
  end if;
  if p_source_id is null or p_source_id !~ '^(tkn|ype)_(test|live)_[A-Za-z0-9_-]{8,100}$' then
    raise exception 'Invalid source';
  end if;
  if p_source_id like 'ype_%' and (coalesce(p_has_3ds,false) or o.payment_amount_minor>200000) then
    raise exception 'Yape does not support card 3DS or payments above PEN 2000';
  end if;
  if o.payment_charge_state='requires_3ds' then
    if not coalesce(p_has_3ds,false) or o.payment_charge_attempt_id is null
      or o.payment_charge_source_id is distinct from p_source_id
      or o.payment_charge_device_id is distinct from p_device_id then
      return jsonb_build_object('state','requires_3ds','claimed',false);
    end if;
  elsif o.payment_charge_state is distinct from 'idle' or coalesce(p_has_3ds,false) then
    return jsonb_build_object('state',o.payment_charge_state,'claimed',false);
  elsif o.payment_charge_attempt_id is not null or o.payment_charge_source_id is not null
    or o.payment_charge_device_id is not null then
    return jsonb_build_object('state','blocked','claimed',false);
  end if;
  if o.payment_charge_id is not null or a.provider_charge_id is not null then
    return jsonb_build_object('state','blocked','claimed',false);
  end if;
  attempt_id:=gen_random_uuid();
  update public.orders set payment_charge_state='submitting',payment_charge_attempt_id=attempt_id,
    payment_charge_source_id=p_source_id,payment_charge_device_id=p_device_id where id=o.id;
  return jsonb_build_object('state','submitting','claimed',true,'attempt_id',attempt_id);
end $$;

revoke all on function public.prepare_culqi_token_session(uuid) from public,anon,authenticated;
revoke all on function public.claim_culqi_charge(uuid,text,text,boolean) from public,anon,authenticated;
grant execute on function public.prepare_culqi_token_session(uuid) to service_role;
grant execute on function public.claim_culqi_charge(uuid,text,text,boolean) to service_role;

-- Deliberately preserve webhook, expiry, confirmation and capacity rules. A failed
-- reservation retains its hold until its original deadline; later verified
-- success remains subject to the existing late-payment reconciliation path.
commit;
